import { useState, useEffect } from 'react'
import { useAuth } from '@contexts/AuthContext'
import { supabase } from '@lib/supabase'
import { CalendarView, TimeSelector } from '@components/talent/CalendarView'
import { Calendar as CalendarIcon, AlertCircle, Save } from 'lucide-react'
import { format } from 'date-fns'
import toast from 'react-hot-toast'

const CalendarPage = () => {
  const { photographerProfile } = useAuth()
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [bookedDates, setBookedDates] = useState([])
  const [availabilitySlots, setAvailabilitySlots] = useState([])
  const [pendingRequests, setPendingRequests] = useState(0)
  const [selectedDate, setSelectedDate] = useState(null)
  const [selectedTime, setSelectedTime] = useState(null)

  useEffect(() => {
    if (photographerProfile) {
      loadCalendarData()
    }
  }, [photographerProfile])

  const loadCalendarData = async () => {
    if (!photographerProfile) return

    try {
      // Load booked dates from bookings table
      const { data: bookings, error: bookingsError } = await supabase
        .from('bookings')
        .select('event_date')
        .eq('photographer_id', photographerProfile.id)
        .in('booking_status', ['pending', 'confirmed'])

      if (bookingsError) throw bookingsError

      const bookedDatesList = bookings?.map(b => b.event_date) || []
      setBookedDates(bookedDatesList)

      // Count pending requests
      const pendingCount = bookings?.filter(b => b.booking_status === 'pending').length || 0
      setPendingRequests(pendingCount)

      // Load existing availability slots
      const { data: availability, error: availError } = await supabase
        .from('photographer_availability')
        .select('*')
        .eq('photographer_id', photographerProfile.id)
        .order('date', { ascending: true })
        .order('time_start', { ascending: true })

      if (availError) throw availError

      setAvailabilitySlots(availability || [])
    } catch (error) {
      console.error('Error loading calendar data:', error)
      toast.error('Failed to load calendar data')
    } finally {
      setLoading(false)
    }
  }

  const handleDateSelect = (date) => {
    setSelectedDate(date)
    setSelectedTime(null)
  }

  const handleTimeSelect = (time) => {
    setSelectedTime(time)
  }

  const handleSaveAvailability = async () => {
    if (!selectedDate || !selectedTime) {
      toast.error('Please select both a date and time')
      return
    }

    setSaving(true)

    try {
      const { error } = await supabase
        .from('photographer_availability')
        .insert({
          photographer_id: photographerProfile.id,
          date: format(selectedDate, 'yyyy-MM-dd'),
          time_start: selectedTime.start,
          time_end: selectedTime.end,
          is_booked: false
        })

      if (error) throw error

      toast.success('Availability added successfully')

      // Reset selections and reload data
      setSelectedDate(null)
      setSelectedTime(null)
      await loadCalendarData()
    } catch (error) {
      console.error('Error saving availability:', error)
      if (error.code === '23505') {
        toast.error('This time slot is already marked as available')
      } else {
        toast.error('Failed to save availability')
      }
    } finally {
      setSaving(false)
    }
  }

  const handleRemoveSlot = async (slotId) => {
    try {
      const { error } = await supabase
        .from('photographer_availability')
        .delete()
        .eq('id', slotId)

      if (error) throw error

      toast.success('Availability slot removed')
      await loadCalendarData()
    } catch (error) {
      console.error('Error removing slot:', error)
      toast.error('Failed to remove slot')
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Booking Calendar</h1>
        <p className="mt-1 text-sm text-gray-600">
          Manage your availability and view upcoming bookings
        </p>
      </div>

      {/* Pending Requests Alert */}
      {pendingRequests > 0 && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <div className="flex items-center">
            <AlertCircle className="w-5 h-5 text-yellow-600 mr-3" aria-hidden="true" />
            <div>
              <div className="font-medium text-yellow-900">
                {pendingRequests} pending booking {pendingRequests === 1 ? 'request' : 'requests'}
              </div>
              <div className="text-sm text-yellow-700 mt-1">
                Review and respond to your pending booking requests
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Calendar */}
      <div className="grid lg:grid-cols-2 gap-6">
        <div>
          <CalendarView
            bookedDates={bookedDates}
            onDateSelect={handleDateSelect}
            selectedDate={selectedDate}
          />
        </div>

        <div className="space-y-6">
          {/* Time Selector */}
          {selectedDate && (
            <div>
              <div className="mb-4">
                <h3 className="text-sm font-medium text-gray-700">
                  Selected Date: {format(selectedDate, 'MMMM d, yyyy')}
                </h3>
              </div>
              <TimeSelector
                selectedTime={selectedTime}
                onTimeSelect={handleTimeSelect}
              />

              {/* Continue Button */}
              {selectedDate && selectedTime && (
                <div className="mt-6">
                  <button
                    onClick={handleSaveAvailability}
                    disabled={saving}
                    className="w-full inline-flex items-center justify-center px-6 py-3 border border-transparent text-base font-medium rounded-md text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50"
                  >
                    {saving ? (
                      <>
                        <div className="animate-spin rounded-full h-5 w-5 border-t-2 border-b-2 border-white mr-2" />
                        Saving...
                      </>
                    ) : (
                      <>
                        <Save className="w-5 h-5 mr-2" aria-hidden="true" />
                        Save Availability
                      </>
                    )}
                  </button>
                </div>
              )}
            </div>
          )}

          {/* Info Box */}
          {!selectedDate && (
            <div className="bg-gray-50 border border-gray-200 rounded-lg p-6">
              <CalendarIcon className="w-8 h-8 text-gray-400 mb-3" aria-hidden="true" />
              <h3 className="font-medium text-gray-900 mb-2">Select a Date</h3>
              <p className="text-sm text-gray-600">
                Click on an available date in the calendar to set your availability.
                Dates marked in red are already booked.
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Availability Slots List */}
      {availabilitySlots.length > 0 && (
        <div className="bg-white rounded-lg border border-gray-200 p-6">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">Your Availability</h2>
          <div className="space-y-2">
            {availabilitySlots.slice(0, 10).map(slot => (
              <div
                key={slot.id}
                className="flex items-center justify-between py-3 px-4 bg-gray-50 rounded-lg"
              >
                <div>
                  <div className="font-medium text-gray-900">
                    {format(new Date(slot.date), 'MMMM d, yyyy')}
                  </div>
                  <div className="text-sm text-gray-600">
                    {slot.time_start} - {slot.time_end}
                  </div>
                </div>
                {!slot.is_booked && (
                  <button
                    onClick={() => handleRemoveSlot(slot.id)}
                    className="text-sm text-red-600 hover:text-red-700 font-medium"
                    aria-label={`Remove availability for ${format(new Date(slot.date), 'MMMM d, yyyy')}`}
                  >
                    Remove
                  </button>
                )}
                {slot.is_booked && (
                  <span className="text-sm text-green-600 font-medium">Booked</span>
                )}
              </div>
            ))}
          </div>
          {availabilitySlots.length > 10 && (
            <p className="mt-4 text-sm text-gray-500 text-center">
              Showing 10 of {availabilitySlots.length} slots
            </p>
          )}
        </div>
      )}
    </div>
  )
}

export default CalendarPage